import { Alert, Box, Button, Chip, Grid, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';
import dayjs from 'dayjs';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import CalendarTodayOutlinedIcon from '@mui/icons-material/CalendarTodayOutlined';
import PhoneOutlinedIcon from '@mui/icons-material/PhoneOutlined';
import HomeOutlinedIcon from '@mui/icons-material/HomeOutlined';
import BadgeOutlinedIcon from '@mui/icons-material/BadgeOutlined';
import EventAvailableOutlinedIcon from '@mui/icons-material/EventAvailableOutlined';
import { IPatientCard } from '../../../../core/Interface/patient.interface';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';
const ALERT_RED = '#DC2626';

const formatDisplayDate = (value?: string) => {
  if (!value || !dayjs(value).isValid()) {
    return '—';
  }

  return dayjs(value).format('MMM D, YYYY');
};

interface IPatientBasicCardProps extends IPatientCard {
  appointmentDisabled?: boolean;
  onAddAppointment?: () => void;
}

const PatientBasicCard = ({
  patientNumber,
  name,
  mobile,
  address,
  dateOfBirth,
  message,
  age,
  appointmentDisabled = true,
  onAddAppointment,
}: IPatientBasicCardProps) => (
  <Grid
    item
    lg={4}
    sm={12}
    xs={12}
  >
    <Box
      sx={{
        background: '#fff',
        border: `1px solid ${alpha(TEAL, 0.16)}`,
        borderRadius: '16px',
        boxShadow: `0 18px 42px ${alpha(NAVY, 0.08)}`,
        height: '100%',
        minHeight: 0,
        overflow: 'hidden',
        position: 'relative',
      }}
    >
      <Box
        sx={{
          background: `linear-gradient(90deg, ${TEAL} 0%, ${alpha(MID, 0.55)} 100%)`,
          height: 4,
        }}
      />

      <Box
        sx={{
          alignItems: 'center',
          background: `linear-gradient(180deg, ${alpha('#fff', 0.98)} 0%, ${alpha(TEAL, 0.03)} 100%)`,
          borderBottom: `1px solid ${alpha(TEAL, 0.08)}`,
          display: 'flex',
          justifyContent: 'space-between',
          px: 2.25,
          py: 1.5,
        }}
      >
        <Box>
          <Typography
            sx={{
              color: alpha(NAVY, 0.55),
              fontSize: 11,
              fontWeight: 800,
              letterSpacing: '0.55px',
              textTransform: 'uppercase',
            }}
          >
            Patient Profile
          </Typography>
          <Typography
            sx={{
              color: alpha(NAVY, 0.42),
              fontSize: 12,
              fontWeight: 600,
              lineHeight: 1.2,
              mt: 0.35,
            }}
          >
            {name ? 'Current patient record' : 'Waiting for patient search'}
          </Typography>
        </Box>

        <Button
          disabled={appointmentDisabled}
          onClick={onAddAppointment}
          startIcon={<EventAvailableOutlinedIcon sx={{ fontSize: 16 }} />}
          sx={{
            background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
            borderRadius: '10px',
            boxShadow: `0 4px 14px ${alpha('#2563EB', 0.45)}`,
            color: '#fff',
            fontSize: 12,
            fontWeight: 800,
            height: 38,
            letterSpacing: '0.2px',
            minWidth: 0,
            px: 2,
            '&:hover': {
              background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)',
            },
            '&:disabled': {
              background: alpha(NAVY, 0.14),
              boxShadow: 'none',
              color: alpha('#fff', 0.88),
              opacity: 1,
            },
          }}
          variant="contained"
        >
          Appointment
        </Button>
      </Box>

      {/* patient avatar area */}
      <Box
        sx={{
          alignItems: 'center',
          background: `linear-gradient(180deg, ${alpha(TEAL, 0.05)} 0%, ${alpha(MID, 0.04)} 100%)`,
          borderBottom: `1px solid ${alpha(TEAL, 0.08)}`,
          display: 'flex',
          flexDirection: 'column',
          gap: 1.1,
          px: 2.5,
          pb: 2.5,
          pt: 2.75,
          textAlign: 'center',
        }}
      >
        <Box
          sx={{
            alignItems: 'center',
            background: name
              ? `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`
              : alpha(NAVY, 0.08),
            boxShadow: name
              ? `0 14px 28px ${alpha(TEAL, 0.26)}`
              : 'none',
            borderRadius: '50%',
            display: 'flex',
            height: 76,
            justifyContent: 'center',
            position: 'relative',
            width: 76,
            '&::after': {
              border: `1px solid ${alpha(name ? TEAL : NAVY, 0.18)}`,
              borderRadius: '50%',
              content: '""',
              inset: -8,
              position: 'absolute',
            },
          }}
        >
          <PersonOutlineIcon sx={{ color: name ? '#fff' : alpha(NAVY, 0.3), fontSize: 34 }} />
        </Box>

        {name ? (
          <>
            <Typography
              sx={{
                color: NAVY,
                fontSize: 13,
                fontWeight: 700,
                letterSpacing: '0.45px',
                textTransform: 'uppercase',
              }}
            >
              Patient Name
            </Typography>
            <Typography
              sx={{
                color: NAVY,
                fontSize: 18,
                fontWeight: 800,
                lineHeight: 1.2,
                maxWidth: '100%',
                wordBreak: 'break-word',
              }}
            >
              {name}
            </Typography>
            <Chip
              label={`ID: ${patientNumber}`}
              size="small"
              sx={{
                background: alpha('#fff', 0.92),
                border: `1px solid ${alpha(TEAL, 0.28)}`,
                borderRadius: '10px',
                color: TEAL,
                fontSize: 13,
                fontWeight: 900,
                height: 34,
                letterSpacing: '0.55px',
                px: 1.25,
                '& .MuiChip-label': { px: 1.2 },
              }}
            />
          </>
        ) : (
          <Typography
            sx={{ color: alpha(NAVY, 0.38), fontSize: 13, fontWeight: 600 }}
          >
            No patient selected
          </Typography>
        )}
      </Box>

      {/* details / state */}
      <Box
        sx={{
          background: `linear-gradient(180deg, #fff 0%, ${alpha(TEAL, 0.015)} 100%)`,
          px: 2.25,
          pt: 2,
          pb: 2.5,
        }}
      >
        {!message && !name && (
          <Alert
            severity="info"
            sx={{ borderRadius: '10px', fontSize: 13 }}
            variant="outlined"
          >
            Search and find the patient
          </Alert>
        )}

        {!name && message && (
          <Alert
            severity="warning"
            sx={{ borderRadius: '10px', fontSize: 13 }}
            variant="outlined"
          >
            {message}
          </Alert>
        )}

        {name && (
          <Box
            sx={{
              display: 'grid',
              gap: 1.1,
              gridTemplateColumns: {
                xs: '1fr',
                sm: 'repeat(2, minmax(0, 1fr))',
                lg: 'repeat(2, minmax(0, 1fr))',
              },
            }}
          >
            <DetailCard
              // eslint-disable-next-line max-len
              icon={<CalendarTodayOutlinedIcon sx={{ fontSize: 15, color: TEAL }} />}
              label="Date of Birth"
              span={{ lg: 1, sm: 1, xs: 1 }}
              value={formatDisplayDate(dateOfBirth)}
            />
            <DetailCard
              icon={<BadgeOutlinedIcon sx={{ fontSize: 15, color: TEAL }} />}
              label="Age"
              span={{ lg: 1, sm: 1, xs: 1 }}
              value={age ? String(age) : '—'}
            />
            <DetailCard
              icon={<PhoneOutlinedIcon sx={{ fontSize: 15, color: TEAL }} />}
              label="Mobile"
              span={{ lg: 1, sm: 1, xs: 1 }}
              value={mobile || '—'}
            />
            <DetailCard
              icon={<HomeOutlinedIcon sx={{ fontSize: 15, color: TEAL }} />}
              label="Address"
              span={{ lg: 1, sm: 1, xs: 1 }}
              value={address || '—'}
            />
          </Box>
        )}
      </Box>
    </Box>
  </Grid>
);

// eslint-disable-next-line react/no-multi-comp
const DetailCard = ({
  icon,
  label,
  span,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  span: { lg: number; sm: number; xs: number };
  value: string;
}) => (
  <Box
    sx={{
      alignItems: 'flex-start',
      background: `linear-gradient(180deg, ${alpha(TEAL, 0.045)} 0%, ${alpha('#fff', 0.98)} 100%)`,
      border: `1px solid ${alpha(TEAL, 0.12)}`,
      borderRadius: '12px',
      display: 'flex',
      gap: 1.1,
      minHeight: 74,
      p: 1.2,
      gridColumn: {
        xs: `span ${span.xs}`,
        sm: `span ${span.sm}`,
        lg: `span ${span.lg}`,
      },
    }}
  >
    <Box
      sx={{
        alignItems: 'center',
        background: alpha(TEAL, 0.1),
        border: `1px solid ${alpha(TEAL, 0.12)}`,
        borderRadius: '10px',
        display: 'flex',
        flexShrink: 0,
        height: 36,
        justifyContent: 'center',
        width: 36,
      }}
    >
      {icon}
    </Box>
    <Box sx={{ minWidth: 0 }}>
      <Typography
        sx={{
          color: alpha(NAVY, 0.45),
          fontSize: 10,
          fontWeight: 800,
          letterSpacing: '0.5px',
          lineHeight: 1.1,
          textTransform: 'uppercase',
        }}
      >
        {label}
      </Typography>
      <Typography
        sx={{
          color: NAVY,
          fontSize: 14,
          fontWeight: 800,
          lineHeight: 1.35,
          mt: 0.5,
          overflowWrap: 'anywhere',
        }}
      >
        {value}
      </Typography>
    </Box>
  </Box>
);

export default PatientBasicCard;
