import React, { useMemo } from 'react';
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  IconButton,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { useFormik } from 'formik';
import EventAvailableOutlinedIcon from '@mui/icons-material/EventAvailableOutlined';
import CloseIcon from '@mui/icons-material/Close';
import dayjs from 'dayjs';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { theme } from '../../../../theme';
import { useNotifier } from '../../../../core/Notifier';
import { useAddAppointmentMutation } from '../../../posApi';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID = '#1E3A8A';

interface IAddAppointment {
  handleCloseDialog: (close: boolean) => void;
  openModel?: boolean;
  patientId: string;
  patientName?: string;
}

const getErrorMessage = (error: unknown) => {
  if (
    error &&
    typeof error === 'object' &&
    'data' in error &&
    error.data &&
    typeof error.data === 'object' &&
    'message' in error.data
  ) {
    return String(error.data.message);
  }

  if (error instanceof Error) {
    return error.message;
  }

  return 'Unable to save appointment';
};

const getCurrentUtcDate = () => new Date().toISOString().slice(0, 10);
const getCurrentUtcTime = () => new Date().toISOString().slice(11, 16);
const buildUtcDateTime = (dateUtc: string, timeUtc: string) => {
  if (!dateUtc || !timeUtc) {
    return '';
  }

  const normalizedTime = timeUtc.length === 5 ? `${timeUtc}:00` : timeUtc;
  return `${dateUtc}T${normalizedTime}Z`;
};

const AddAppointment = ({
  handleCloseDialog,
  openModel = true,
  patientId,
  patientName,
}: IAddAppointment) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { showErrorMessage, showMessage } = useNotifier();
  const [addAppointment, { isLoading }] = useAddAppointmentMutation();
  const [open] = React.useState(openModel);

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    enableReinitialize: true,
    initialValues: {
      dateUtc: getCurrentUtcDate(),
      remarks: '',
      timeUtc: getCurrentUtcTime(),
    },
    onSubmit: async (values) => {
      try {
        const response = await addAppointment({
          dateTime: buildUtcDateTime(values.dateUtc, values.timeUtc),
          patientId,
          remark: values.remarks.trim(),
        }).unwrap();

        if (!response.status) {
          showErrorMessage(response.message);
          return;
        }

        showMessage(response.message);
        handleClose();
      } catch (error) {
        showErrorMessage(getErrorMessage(error));
      }
    },
  });

  const formValid = useMemo(
    () => !!formik.values.dateUtc && !!formik.values.timeUtc,
    [formik.values.dateUtc, formik.values.timeUtc],
  );

  return (
    <Dialog
      PaperProps={{
        component: 'form',
        noValidate: true,
        onSubmit: formik.handleSubmit,
        sx: {
          borderRadius: '16px',
          overflow: 'hidden',
          boxShadow: `0 24px 64px ${alpha(NAVY, 0.22)}`,
        },
      }}
      fullScreen={isMobile}
      fullWidth
      maxWidth="sm"
      onClose={handleClose}
      open={open}
    >
        <Box
          sx={{
            background: `linear-gradient(135deg, ${NAVY} 0%, ${MID} 50%, ${TEAL} 100%)`,
            overflow: 'hidden',
            px: 3,
            py: 2.5,
            position: 'relative',
          }}
        >
          <Box
            sx={{
              background: 'rgba(255,255,255,0.07)',
              borderRadius: '50%',
              height: 120,
              inset: 'auto -30px -60px auto',
              pointerEvents: 'none',
              position: 'absolute',
              width: 120,
            }}
          />
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              justifyContent: 'space-between',
              position: 'relative',
            }}
          >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  backdropFilter: 'blur(8px)',
                  background: 'rgba(255,255,255,0.14)',
                  border: '1px solid rgba(255,255,255,0.2)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 40,
                  justifyContent: 'center',
                  width: 40,
                }}
              >
                <EventAvailableOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
              </Box>
              <Box>
                <Typography
                  sx={{
                    color: '#fff',
                    fontSize: '1rem',
                    fontWeight: 800,
                    letterSpacing: '-0.01em',
                    lineHeight: 1.2,
                  }}
                >
                  Add Appointment
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.68)', fontSize: '0.75rem' }}>
                  {patientName ? `Schedule for ${patientName}` : 'Schedule patient appointment'}
                </Typography>
              </Box>
            </Box>

            <IconButton
              onClick={handleClose}
              size="small"
              sx={{
                background: 'rgba(255,255,255,0.12)',
                border: '1px solid rgba(255,255,255,0.2)',
                borderRadius: '8px',
                color: '#fff',
                height: 32,
                width: 32,
                '&:hover': { background: 'rgba(255,255,255,0.22)' },
              }}
            >
              <CloseIcon sx={{ fontSize: 16 }} />
            </IconButton>
          </Box>
        </Box>

        <DialogTitle sx={{ pb: 0, pt: 2.5 }}>
          <Typography sx={{ color: alpha(NAVY, 0.6), fontSize: 12, fontWeight: 700, letterSpacing: '0.45px', textTransform: 'uppercase' }}>
            UTC Schedule
          </Typography>
        </DialogTitle>

        <DialogContent sx={{ pb: 2, pt: 2 }}>
          <Grid container spacing={2}>
            <FieldItem label="Date (UTC)">
              <LocalizationProvider dateAdapter={AdapterDayjs}>
                <DatePicker
                  InputProps={{ sx: { height: '40px' } }}
                  inputFormat="DD-MM-YYYY"
                  onChange={(date) => {
                    formik.setFieldValue(
                      'dateUtc',
                      date ? dayjs(date).format('YYYY-MM-DD') : '',
                    );
                  }}
                  renderInput={(params) => (
                    <TextField
                      fullWidth
                      size="small"
                      {...params}
                      sx={fieldSx}
                    />
                  )}
                  value={formik.values.dateUtc ? dayjs(formik.values.dateUtc) : null}
                  views={['day', 'month', 'year']}
                />
              </LocalizationProvider>
            </FieldItem>

            <FieldItem label="Time (UTC)">
              <TextField
                fullWidth
                size="small"
                type="time"
                {...formik.getFieldProps('timeUtc')}
                InputLabelProps={{ shrink: true }}
                sx={fieldSx}
              />
            </FieldItem>

            <FieldItem label="Remarks" sm={12}>
              <TextField
                autoComplete="off"
                fullWidth
                multiline
                placeholder="Enter remarks"
                rows={4}
                size="small"
                {...formik.getFieldProps('remarks')}
                sx={fieldSx}
              />
            </FieldItem>
          </Grid>
        </DialogContent>

        <DialogActions sx={{ gap: 1.5, px: 3, pb: 3, pt: 0 }}>
          <Button
            onClick={handleClose}
            sx={{
              borderColor: alpha(NAVY, 0.2),
              borderRadius: '10px',
              color: NAVY,
              fontWeight: 700,
              minWidth: 108,
              px: 3,
            }}
            variant="outlined"
          >
            Cancel
          </Button>
          <Button
            disabled={!formValid || isLoading}
            sx={{
              background: `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`,
              borderRadius: '10px',
              boxShadow: `0 4px 14px ${alpha(TEAL, 0.3)}`,
              color: '#fff',
              fontWeight: 700,
              minWidth: 148,
              px: 3,
              '&:hover': {
                background: `linear-gradient(135deg, ${MID} 0%, ${NAVY} 100%)`,
              },
            }}
            type="submit"
            variant="contained"
          >
            {isLoading ? (
              <CircularProgress
                size={18}
                sx={{ color: '#fff' }}
              />
            ) : (
              'Save Appointment'
            )}
          </Button>
        </DialogActions>
    </Dialog>
  );
};

const fieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(TEAL, 0.03),
    borderRadius: '8px',
    '& fieldset': { borderColor: alpha(TEAL, 0.2) },
    '&:hover fieldset': { borderColor: alpha(TEAL, 0.4) },
    '&.Mui-focused fieldset': { borderColor: TEAL },
  },
};

const FieldItem = ({
  children,
  label,
  sm = 6,
}: {
  children: React.ReactNode;
  label: string;
  sm?: number;
}) => (
  <Grid
    item
    sm={sm}
    xs={12}
  >
    <Typography
      sx={{
        color: alpha(NAVY, 0.5),
        fontSize: 11,
        fontWeight: 700,
        letterSpacing: '0.5px',
        mb: 0.75,
        textTransform: 'uppercase',
      }}
    >
      {label}
    </Typography>
    {children}
  </Grid>
);

export default React.memo(AddAppointment);
