import React, { useMemo, useState } from 'react';
import {
  Chip,
  Box,
  Button,
  CircularProgress,
  Grid,
  InputAdornment,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import dayjs from 'dayjs';
import useUser from '../../../../core/hooks/useUser';
import { useTranslation } from 'react-i18next';
import { useFormik } from 'formik';
import { useNotifier } from '../../../../core/Notifier';
import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/Add';
import MedicalServicesOutlinedIcon from '@mui/icons-material/MedicalServicesOutlined';
import HealingIcon from '@mui/icons-material/Healing';
import EventAvailableOutlinedIcon from '@mui/icons-material/EventAvailableOutlined';
import NotesOutlinedIcon from '@mui/icons-material/NotesOutlined';
import PatientBasicCard from './PatientBasicCard';
import NewPatient from './NewPatient';
import AddAppointment from './AddAppointment';
import {
  useGetPatientByIdQuery,
  useRegisterTreatmentMutation,
} from '../../../posApi';
import PatientHistory from './PatientHistory';
import { Privileges } from '../../../../core/types/commonType';
import { IPatientCard } from '../../../../core/Interface/patient.interface';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';
const ALERT_RED = '#DC2626';

const TreatmentsView = () => {
  const { t } = useTranslation(['common']);
  const { userHasRight } = useUser();
  const { showErrorMessage, showMessage } = useNotifier();
  const [open, setOpen] = useState(false);
  const [openAppointment, setOpenAppointment] = useState(false);
  const [patientNumber, setPatientNumber] = useState<string>('');
  const [registerTreatment, { isLoading: isRegisteringTreatment }] =
    useRegisterTreatmentMutation();

  const { data, isFetching } = useGetPatientByIdQuery(
    patientNumber.split('_')[0],
    { skip: !patientNumber }
  );

  const patient = useMemo(() => {
    if (!data?.data) return { message: data?.message } as IPatientCard;
    const d = data?.data as IPatientCard;
    return { message: data?.message, ...d } as IPatientCard;
  }, [data]);

  const formik = useFormik({
    initialValues: { patientId: '', dissese: '', amount: '', medition: '' },
    onSubmit: async (values) => {
      if (isRegisteringTreatment) return;
      try {
        const response = await registerTreatment({
          ...values,
          patientId: patient.id,
        }).unwrap();
        if (!response.status) {
          showErrorMessage(response.message);
        } else {
          showMessage(response.message);
          formik.resetForm();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formikNew = useFormik({
    initialValues: { patientId: '' },
    onSubmit: async (values) => {
      try {
        setPatientNumber(values.patientId);
      } catch (_e) {
        showErrorMessage('Please check your data');
      }
    },
  });

  return (
    <Box>
      {/* ── Hero banner ───────────────────────────────────────────── */}
      <Box
        sx={{
          background: `linear-gradient(135deg, ${NAVY} 0%, ${MID} 45%, ${TEAL} 100%)`,
          borderRadius: 2,
          color: '#fff',
          mb: 3,
          overflow: 'hidden',
          position: 'relative',
          px: { xs: 2, md: 3 },
          py: { xs: 1.5, md: 2 },
        }}
      >
        {/* decorative blobs */}
        <Box sx={{ background: 'rgba(255,255,255,0.07)', borderRadius: '50%', height: 220, inset: 'auto -60px -100px auto', pointerEvents: 'none', position: 'absolute', width: 220 }} />
        <Box sx={{ background: 'rgba(255,255,255,0.05)', borderRadius: '50%', height: 260, inset: '-100px auto auto 55%', pointerEvents: 'none', position: 'absolute', width: 260 }} />

        <Box
          sx={{
            alignItems: { xs: 'flex-start', sm: 'center' },
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            gap: 2,
            justifyContent: 'space-between',
            position: 'relative',
          }}
        >
          {/* title */}
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
            <Box
              sx={{
                alignItems: 'center',
                backdropFilter: 'blur(8px)',
                background: 'rgba(255,255,255,0.14)',
                border: '1px solid rgba(255,255,255,0.18)',
                borderRadius: '10px',
                display: 'flex',
                height: 44,
                justifyContent: 'center',
                width: 44,
              }}
            >
              <MedicalServicesOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: { xs: '1rem', md: '1.2rem' }, fontWeight: 800, letterSpacing: '-0.02em', lineHeight: 1.2 }}>
                Treatments
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }}>
                Search patient · add treatment · view history
              </Typography>
            </Box>
          </Box>

          {/* search + new-patient */}
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, flexWrap: 'wrap', position: 'relative' }}>
            <form noValidate onSubmit={formikNew.handleSubmit}>
              <Box sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                <TextField
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon sx={{ color: alpha('#fff', 0.6), fontSize: 18 }} />
                      </InputAdornment>
                    ),
                    sx: {
                      color: '#fff',
                      '& .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,0.35)' },
                      '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,0.6)' },
                      '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderColor: '#fff' },
                      '& input::placeholder': { color: 'rgba(255,255,255,0.5)' },
                    },
                  }}
                  autoComplete="off"
                  name="patientId"
                  onChange={formikNew.handleChange}
                  placeholder="Patient Number"
                  size="small"
                  sx={{ width: 240 }}
                  value={formikNew.values.patientId}
                  variant="outlined"
                />
                <Button
                  disabled={isFetching}
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    backdropFilter: 'blur(4px)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    borderRadius: '8px',
                    color: '#fff',
                    fontWeight: 700,
                    height: 40,
                    px: 2,
                    '&:hover': { background: 'rgba(255,255,255,0.28)' },
                    '&:disabled': { opacity: 0.6 },
                  }}
                  type="submit"
                  variant="outlined"
                >
                  {isFetching ? <CircularProgress
                    size={16}
                    sx={{ color: '#fff' }}
                                /> : t('common:search')}
                </Button>
              </Box>
            </form>

            {userHasRight(Privileges.PatientAdd) && (
              <Button
                onClick={() => setOpen(true)}
                startIcon={<AddIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                  borderRadius: '8px',
                  boxShadow: `0 4px 14px ${alpha('#2563EB', 0.45)}`,
                  color: '#fff',
                  fontWeight: 700,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                }}
                variant="contained"
              >
                {t('common:create')} Patient
              </Button>
            )}
          </Box>
        </Box>
      </Box>

      {/* ── Patient card + treatment form ─────────────────────────── */}
      <Grid
        container
        spacing={2}
      >
        <PatientBasicCard
          address={patient?.address || ''}
          age={patient?.age}
          appointmentDisabled={!patient?.id}
          dateOfBirth={patient?.dateOfBirth}
          id={patient?.id}
          message={patient?.message}
          mobile={patient?.mobile}
          name={patient?.name}
          nextAppointmentDateTime={patient?.nextAppointmentDateTime}
          nextAppointmentRemark={patient?.nextAppointmentRemark}
          onAddAppointment={() => setOpenAppointment(true)}
          patientNumber={patient?.patientNumber}
        />

        {/* Treatment form */}
        <Grid
          item
          lg={8}
          sm={12}
          xs={12}
        >
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              gap: 2,
            }}
          >
            <AppointmentSummaryCard
              nextAppointmentDateTime={patient?.nextAppointmentDateTime}
              nextAppointmentRemark={patient?.nextAppointmentRemark}
              patientName={patient?.name}
            />

            <Box
              sx={{
                background: '#fff',
                border: `1px solid ${alpha(TEAL, 0.18)}`,
                borderRadius: '12px',
                boxShadow: `0 4px 24px ${alpha(NAVY, 0.06)}`,
                overflow: 'hidden',
              }}
            >
              {/* card header */}
              <Box sx={{ background: `linear-gradient(90deg, ${TEAL} 0%, ${alpha(TEAL, 0.5)} 100%)`, height: 3 }} />
              <Box
                sx={{
                  alignItems: { xs: 'flex-start', sm: 'center' },
                  display: 'flex',
                  flexDirection: { xs: 'column', sm: 'row' },
                  gap: 1.5,
                  justifyContent: 'space-between',
                  px: 3,
                  pt: 2.5,
                  pb: 1,
                }}
              >
                <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
                  <Box
                    sx={{
                      alignItems: 'center',
                      background: alpha(TEAL, 0.1),
                      border: `1px solid ${alpha(TEAL, 0.2)}`,
                      borderRadius: '8px',
                      display: 'flex',
                      height: 36,
                      justifyContent: 'center',
                      width: 36,
                    }}
                  >
                    <HealingIcon sx={{ color: TEAL, fontSize: 18 }} />
                  </Box>
                  <Typography sx={{ color: NAVY, fontWeight: 700, fontSize: 15 }}>
                    New Treatment
                  </Typography>
                </Box>
              </Box>

              <form noValidate onSubmit={formik.handleSubmit}>
                <Box sx={{ px: 3, pb: 3, pt: 1 }}>
                  <Grid
                    container
                    spacing={2}
                  >
                    <Grid
                      item
                      sm={6}
                      xs={12}
                    >
                      <FormField label="Disease">
                        <TextField
                          autoComplete="off"
                          fullWidth
                          multiline
                          placeholder="Enter disease / diagnosis"
                          rows={3}
                          size="small"
                          {...formik.getFieldProps('dissese')}
                          sx={fieldSx}
                        />
                      </FormField>
                    </Grid>
                    <Grid
                      item
                      sm={6}
                      xs={12}
                    >
                      <FormField label="Medication">
                        <TextField
                          autoComplete="off"
                          fullWidth
                          multiline
                          placeholder="Enter medication prescribed"
                          rows={3}
                          size="small"
                          {...formik.getFieldProps('medition')}
                          sx={fieldSx}
                        />
                      </FormField>
                    </Grid>
                    <Grid
                      item
                      sm={6}
                      xs={12}
                    >
                      <FormField label="Amount (LKR)">
                        <TextField
                          fullWidth
                          placeholder="0.00"
                          size="small"
                          type="number"
                          inputProps={{ step: 'any' }}
                          {...formik.getFieldProps('amount')}
                          sx={fieldSx}
                        />
                      </FormField>
                    </Grid>
                    <Grid
                      item
                      sm={6}
                      sx={{ display: 'flex', alignItems: 'flex-end' }}
                      xs={12}
                    >
                      <Button
                        disabled={!patient?.patientNumber || isRegisteringTreatment}
                        fullWidth
                        sx={{
                          background: patient?.patientNumber
                            ? `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`
                            : undefined,
                          borderRadius: '8px',
                          boxShadow: patient?.patientNumber
                            ? `0 4px 14px ${alpha(TEAL, 0.4)}`
                            : undefined,
                          color: '#fff',
                          fontWeight: 700,
                          height: 44,
                          '&:hover': {
                            background: `linear-gradient(135deg, ${MID} 0%, ${NAVY} 100%)`,
                          },
                          '&:disabled': { opacity: 0.5 },
                        }}
                        type="submit"
                        variant="contained"
                      >
                        {isRegisteringTreatment ? (
                          <CircularProgress
                            size={18}
                            sx={{ color: '#fff' }}
                          />
                        ) : (
                          `${t('common:submit')} Treatment`
                        )}
                      </Button>
                    </Grid>
                  </Grid>
                </Box>
              </form>
            </Box>
          </Box>
        </Grid>
      </Grid>

      {/* ── History ───────────────────────────────────────────────── */}
      <PatientHistory treatements={patient.treatements} />

      {open && (
        <NewPatient
          data={undefined}
          handleCloseDialog={() => setOpen(false)}
          openModel={open}
          title="Create New Patient"
        />
      )}

      {openAppointment && patient?.id && (
        <AddAppointment
          handleCloseDialog={() => setOpenAppointment(false)}
          openModel={openAppointment}
          patientId={patient.id}
          patientName={patient.name}
        />
      )}
    </Box>
  );
};

// ── helpers ───────────────────────────────────────────────────────────────────

const fieldSx = {
  '& .MuiOutlinedInput-root': {
    borderRadius: '8px',
    backgroundColor: alpha('#0F8B8D', 0.03),
    '& fieldset': { borderColor: alpha('#0F8B8D', 0.2) },
    '&:hover fieldset': { borderColor: alpha('#0F8B8D', 0.4) },
    '&.Mui-focused fieldset': { borderColor: '#0F8B8D' },
  },
};

const AppointmentSummaryCard = ({
  nextAppointmentDateTime,
  nextAppointmentRemark,
  patientName,
}: {
  nextAppointmentDateTime?: string;
  nextAppointmentRemark?: string;
  patientName?: string;
}) => {
  const hasAppointment = !!nextAppointmentDateTime && dayjs(nextAppointmentDateTime).isValid();

  return (
    <Box
      sx={{
        background: '#fff',
        border: `1px solid ${alpha(ALERT_RED, 0.18)}`,
        borderRadius: '12px',
        boxShadow: `0 10px 28px ${alpha(ALERT_RED, 0.08)}`,
        overflow: 'hidden',
      }}
    >
      <Box sx={{ background: `linear-gradient(90deg, ${ALERT_RED} 0%, #F97316 100%)`, height: 4 }} />

      <Box sx={{ px: 3, py: 2.5 }}>
        <Box
          sx={{
            alignItems: { xs: 'flex-start', sm: 'center' },
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            gap: 1.5,
            justifyContent: 'space-between',
            mb: 2,
          }}
        >
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.25 }}>
            <Box
              sx={{
                alignItems: 'center',
                background: alpha(ALERT_RED, 0.08),
                border: `1px solid ${alpha(ALERT_RED, 0.16)}`,
                borderRadius: '10px',
                display: 'flex',
                height: 38,
                justifyContent: 'center',
                width: 38,
              }}
            >
              <EventAvailableOutlinedIcon sx={{ color: ALERT_RED, fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: NAVY, fontSize: 15, fontWeight: 800 }}>
                Next Appointment
              </Typography>
              <Typography sx={{ color: alpha(NAVY, 0.45), fontSize: 12, fontWeight: 600 }}>
                {patientName ? `${patientName}'s scheduled visit` : 'Scheduled visit details'}
              </Typography>
            </Box>
          </Box>

          <Chip
            label={hasAppointment ? 'Scheduled' : 'Not Scheduled'}
            size="small"
            sx={{
              background: hasAppointment ? alpha(ALERT_RED, 0.1) : alpha(NAVY, 0.08),
              border: `1px solid ${hasAppointment ? alpha(ALERT_RED, 0.22) : alpha(NAVY, 0.12)}`,
              color: hasAppointment ? ALERT_RED : alpha(NAVY, 0.55),
              fontSize: 11,
              fontWeight: 800,
            }}
          />
        </Box>

        {hasAppointment ? (
          <Box sx={{ display: 'grid', gap: 1.25, gridTemplateColumns: { xs: '1fr', lg: 'repeat(2, minmax(0, 1fr))' } }}>
            <Box
              sx={{
                background: `linear-gradient(135deg, ${alpha(ALERT_RED, 0.1)} 0%, ${alpha('#fff', 0.98)} 100%)`,
                border: `1px solid ${alpha(ALERT_RED, 0.18)}`,
                borderRadius: '14px',
                gridColumn: { xs: 'span 1', lg: 'span 2' },
                p: 1.75,
              }}
            >
              <Typography sx={{ color: alpha(ALERT_RED, 0.8), fontSize: 11, fontWeight: 800, letterSpacing: '0.45px', textTransform: 'uppercase' }}>
                Appointment Date Time
              </Typography>
              <Typography sx={{ color: NAVY, fontSize: 20, fontWeight: 900, lineHeight: 1.25, mt: 0.5 }}>
                {dayjs(nextAppointmentDateTime).format('dddd, MMM D, YYYY')}
              </Typography>
              <Typography sx={{ color: ALERT_RED, fontSize: 13, fontWeight: 800, mt: 0.6 }}>
                {dayjs(nextAppointmentDateTime).format('hh:mm A')}
              </Typography>
            </Box>

            <SummaryTile
              icon={<NotesOutlinedIcon sx={{ color: ALERT_RED, fontSize: 18 }} />}
              label="Remark"
              value={nextAppointmentRemark || 'No remark added'}
              valueFontSize={10}
            />
            <SummaryTile
              icon={<EventAvailableOutlinedIcon sx={{ color: ALERT_RED, fontSize: 18 }} />}
              label="Status"
              value="Upcoming appointment"
            />
          </Box>
        ) : (
          <Box
            sx={{
              background: `linear-gradient(135deg, ${alpha(ALERT_RED, 0.08)} 0%, ${alpha('#fff', 0.98)} 100%)`,
              border: `1px solid ${alpha(ALERT_RED, 0.14)}`,
              borderRadius: '14px',
              p: 2,
            }}
          >
            <Typography sx={{ color: alpha(ALERT_RED, 0.85), fontSize: 11, fontWeight: 800, letterSpacing: '0.45px', textTransform: 'uppercase' }}>
              Appointment Date Time
            </Typography>
            <Typography sx={{ color: NAVY, fontSize: 16, fontWeight: 800, mt: 0.55 }}>
              No appointment scheduled
            </Typography>
            <Typography sx={{ color: alpha(NAVY, 0.5), fontSize: 13, fontWeight: 600, mt: 0.5 }}>
              Use the appointment button to register the next visit.
            </Typography>
          </Box>
        )}
      </Box>
    </Box>
  );
};

const SummaryTile = ({
  icon,
  label,
  value,
  valueFontSize = 14,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  valueFontSize?: number;
}) => (
  <Box
    sx={{
      alignItems: 'flex-start',
      background: `linear-gradient(180deg, ${alpha(ALERT_RED, 0.045)} 0%, ${alpha('#fff', 0.98)} 100%)`,
      border: `1px solid ${alpha(ALERT_RED, 0.12)}`,
      borderRadius: '12px',
      display: 'flex',
      gap: 1,
      minHeight: 76,
      p: 1.3,
    }}
  >
    <Box
      sx={{
        alignItems: 'center',
        background: alpha(ALERT_RED, 0.08),
        border: `1px solid ${alpha(ALERT_RED, 0.12)}`,
        borderRadius: '10px',
        display: 'flex',
        flexShrink: 0,
        height: 36,
        justifyContent: 'center',
        width: 36,
      }}
    >
      {icon}
    </Box>
    <Box sx={{ minWidth: 0 }}>
      <Typography sx={{ color: alpha(NAVY, 0.45), fontSize: 10, fontWeight: 800, letterSpacing: '0.5px', textTransform: 'uppercase' }}>
        {label}
      </Typography>
      <Typography sx={{ color: NAVY, fontSize: valueFontSize, fontWeight: 800, lineHeight: 1.35, mt: 0.45, overflowWrap: 'anywhere' }}>
        {value}
      </Typography>
    </Box>
  </Box>
);

// eslint-disable-next-line react/no-multi-comp, max-len
const FormField = ({ label, children }: { label: string; children: React.ReactNode }) => (
  <Box>
    <Typography sx={{ color: alpha('#0F1D4D', 0.5), fontSize: 11, fontWeight: 700, mb: 0.75, textTransform: 'uppercase', letterSpacing: '0.5px' }}>
      {label}
    </Typography>
    {children}
  </Box>
);

export default TreatmentsView;
